d=df.copy()
d['band']=pd.cut(d.tenure_months,[0,12,36,72],labels=['1-12','13-36','37-72'])
d['cg']=d.support_calls.clip(upper=5)
for b,g in d.groupby('band'):
    t=g.groupby('contract').churned.agg(['mean','size'])
    c2=stats.chi2_contingency(pd.crosstab(g.contract,g.churned))
    print(b,t.round(3).to_dict('index'),'V',round((c2[0]/len(g))**.5,3),'p',c2[1])
def tr(g):
    r=stats.spearmanr(g.cg,g.churned);return round(r[0],3),r[1]
for k in ['contract','band']:
    for l,g in d.groupby(k):
        print(k,l,g.groupby('cg').churned.mean().round(3).to_dict(),g.cg.value_counts().sort_index().to_dict(),tr(g))
# logistic via IRLS
X=pd.get_dummies(d.contract)[['month-to-month','one-year']].astype(float)
X['tenure']=d.tenure_months;X['calls']=d.support_calls;X['mc']=d.monthly_charges
X.insert(0,'c',1.0);A=X.values;y=d.churned.values;b=np.zeros(A.shape[1])
for i in range(30):
    p=1/(1+np.exp(-A@b));W=p*(1-p);H=A.T@(A*W[:,None]);b=b+np.linalg.solve(H,A.T@(y-p))
se=np.sqrt(np.diag(np.linalg.inv(H)))
for n,bb,s in zip(X.columns,b,se):print(n,round(np.exp(bb),3),round(np.exp(bb-1.96*s),3),round(np.exp(bb+1.96*s),3))

